function(appinfo, callback) {
        console.log('Install App V2 begin')
        let ret = false

        if (typeof (appinfo) != 'object') {
            callback(-1)
            return ret
        }

        const newAppInfo = mapAppInfoFields(appinfo)
        let installAppObj = getInstalledAppJsonObj()
        if (installAppObj) {
            for (let i = 0; i < installAppObj.AppInfo.length; i++) {
                if (newAppInfo.URL == installAppObj.AppInfo[i].URL) {
                    if (newAppInfo.AppName != installAppObj.AppInfo[i].AppName) {
                        installAppObj.AppInfo[i].AppName = newAppInfo.AppName
                        installAppObj.AppInfo[i].URL = newAppInfo.URL
                        installAppObj.AppInfo[i].Image = newAppInfo.Image
                        writeInstallAppObjToJson(installAppObj)
                        callback(0)
                        return true
                    } else {
                        console.log('same app' + newAppInfo.Id)
                        callback(0)
                        return true
                    }
                }
            }
        }

        if (installAppObj) {
            installAppObj.AppInfo.push(newAppInfo)
        } else {
            installAppObj = { AppInfo: [newAppInfo] }
        }

        ret = writeInstallAppObjToJson(installAppObj)
        callback(0)
        return ret
    }

function(appId, appName, thumbnail, iconSmall, iconBig, appUrl, storetype, callback, configUrl, configUrlDownload, mediaId) {
        console.log('Install App begin' + appId)

        let mydate = new Date()
        let realMonth = mydate.getMonth() + 1
        let StoreType = storetype
        let newApp = {
            'Id': appId,
            'Thumb': thumbnail,
            'Icon_96': iconSmall,
            'Image': thumbnail,
            'URL': appUrl,
            'AppName': appName,
            'Title': appName,
            'configUrl': configUrl,
            'configUrlDownload': configUrlDownload,
            'mediaId': mediaId,
            'IconURL': iconBig,
            'StartCommand': appUrl,
            'InstallTime': mydate.getFullYear() + '-' + realMonth + '-' + mydate.getDate(),
            'RunTimes': 0,
            'StoreType': StoreType,
            'PreInstall': false }
        let installAppObj = getInstalledAppJsonObj()
        if (installAppObj) {
            for (let i = 0; i < installAppObj.AppInfo.length; i++) {
                if (appUrl == installAppObj.AppInfo[i].URL) {
                    if (appName != installAppObj.AppInfo[i].AppName) {
                        installAppObj.AppInfo[i].AppName = appName
                        installAppObj.AppInfo[i].URL = appUrl
                        installAppObj.AppInfo[i].Image = thumbnail
                        ret = writeInstallAppObjToJson(installAppObj)
                        return ret
                    } else {
                        console.log('same app' + appId)
                        return true
                    }
                }
            }
        }
        if (installAppObj) {
            installAppObj.AppInfo.push(newApp)
        } else {
            installAppObj = { AppInfo: [newApp] }
        }

        const ret = writeInstallAppObjToJson(installAppObj)

        callback(0)
        return ret
    }

function(appId, callback) {
        console.log('Uninstall App begin' + appId)

        let installAppObj = getInstalledAppJsonObj()
        let appIndex = 0
        let ret = false
        if (installAppObj != 0) {
            for (appIndex = 0; appIndex < installAppObj.AppInfo.length; appIndex++) {
                if (installAppObj.AppInfo[appIndex].Id == appId) {
                    installAppObj.AppInfo.splice(appIndex, 1)
                    ret = true
                }
            }
            if (ret) {
                writeInstallAppObjToJson(installAppObj)
            }
        }

        callback(ret)
        return true
    }

function(callback) {
        console.log('getInstalledApps')

        let count = 0
        const allAppObj = getAllAppJsonObj()
        let ret = ''

        if (allAppObj.length == 0) {
            errinfo = new Error()
            errinfo.name = 'getInstalledApps'
            errinfo.message = 'There is no App has installed!!!'
            callback(errinfo, null)
        } else {
            let all_apps = allAppObj?.AppInfo
            if(all_apps.length != 0) {
                var newArray = all_apps.filter((item, i, arr) => {
                    return item?.isShowOnLauncher != false
                })
                //console.log(newArray);
            }
            const result = {'AppInfo': newArray}
            ret = JSON.stringify(result)
            callback(null, ret)
        }

        return ret
    }

function(callback) {
        console.log('go to Hisense_GetUpdatesVerInfo')
        var requestMsg = {}
        requestMsg.type = 'getUpdatesVerInfo'

        try {
            if (window.omi_platform) {
                omi_platform.sendPlatformMessage(JSON.stringify(requestMsg))
            }
        } catch (e) {
            // handle the exception
        }

        handleGetVersionEvent = function(version) {
            var message = JSON.parse(version)
            if (!!message && version.indexOf('nssdb') != -1) {
                callback(message)
            }
        }

        if (window.alreadyAddUpdateEventListener == 0) {
            omi_platform.addPlatformEventListener(handleGetVersionEvent)
            window.alreadyAddUpdateEventListener = 1
        }
    }

